{{egy-IPA-R|q=proper noun|o=ˈsaχmat|m=ˈsaχmaʔ|ml=ˈsaχma|l=ˈsaχmə|onote=<ref>{{R:cop:Vycichl|203}}</ref><ref>{{R:egy:Loprieno|59, 60, 63}}</ref>}}
